) VALUES (
    'RULE-AFTER-001', 'v2026.10', 'aftersales',
    '7天无理由退换货规则（受控基准简化自淘宝公开规则）', '【确定性核验契约】仅限已签收订单（order_status=''delivered'' 且 signed_at 非空）：自实际签收时刻（signed_at，Asia/Shanghai 时区）起算滚动 168 小时内（0 <= elapsed_hours <= 168.0，含 168 小时整点边界），且商品完好未拆封（is_opened=false），可申请7天无理由退货；若订单尚未签收（pending/shipped）、已拆封（is_opened=true）或距签收时刻超过 168 小时（elapsed_hours > 168.0），则不支持7天无理由退货。',
    7, 168,
    'signed_at', NULL,
